script:
(function () {
  'use strict';

  var video = document.getElementById('cameraVideo');
  var previewWrap = document.getElementById('cameraPreviewWrap');
  var placeholder = document.getElementById('cameraPlaceholder');
  var previewCanvas = document.getElementById('previewCanvas');
  var gridCanvas = document.getElementById('gridCanvas');
  var deviceSelect = document.getElementById('deviceSelect');
  var selectResolution = document.getElementById('selectResolution');
  var btnStart = document.getElementById('btnStartCamera');
  var btnStop = document.getElementById('btnStopCamera');
  var btnMirror = document.getElementById('btnMirrorToggle');
  var btnFullscreen = document.getElementById('btnFullscreen');
  var btnExitFullscreen = document.getElementById('btnExitFullscreen');
  var fullscreenHint = document.getElementById('fullscreenHint');
  var btnCapture = document.getElementById('btnCapture');
  var selectCountdown = document.getElementById('selectCountdown');
  var checkBurst = document.getElementById('checkBurst');
  var checkFlash = document.getElementById('checkFlash');
  var selectAspect = document.getElementById('selectAspect');
  var selectZoom = document.getElementById('selectZoom');
  var selectRotate = document.getElementById('selectRotate');
  var selectShape = document.getElementById('selectShape');
  var checkGrid = document.getElementById('checkGrid');
  var checkFlipV = document.getElementById('checkFlipV');
  var checkNight = document.getElementById('checkNight');
  var countdownEl = document.getElementById('captureCountdown');
  var flashEl = document.getElementById('captureFlash');
  var diagnosticPanel = document.getElementById('diagnosticPanel');
  var statResolution = document.getElementById('statResolution');
  var statMegapixels = document.getElementById('statMegapixels');
  var statFrameKept = document.getElementById('statFrameKept');
  var statPrintSize = document.getElementById('statPrintSize');
  var statOrientation = document.getElementById('statOrientation');
  var statPngSize = document.getElementById('statPngSize');
  var statJpegSize = document.getElementById('statJpegSize');
  var statDelay = document.getElementById('statDelay');
  var statEffects = document.getElementById('statEffects');
  var statSavedFile = document.getElementById('statSavedFile');
  var statShotCount = document.getElementById('statShotCount');
  var inputFileName = document.getElementById('inputFileName');
  var captureList = document.getElementById('captureList');
  var captureEmpty = document.getElementById('captureEmpty');
  var selectFilter = document.getElementById('selectFilter');
  var selectBalance = document.getElementById('selectBalance');
  var btnResetAdjustments = document.getElementById('btnResetAdjustments');
  var adjustmentsNote = document.getElementById('adjustmentsNote');

  // Slider id suffix -> {default, unit used in its readout}.
  var SLIDERS = {
    Exposure: { def: 0 },
    Brightness: { def: 100, unit: '%' },
    Contrast: { def: 100, unit: '%' },
    Saturation: { def: 100, unit: '%' },
    Hue: { def: 0, unit: '°' },
    Blur: { def: 0, unit: 'px' },
    Grayscale: { def: 0, unit: '%' },
    Sepia: { def: 0, unit: '%' },
    Invert: { def: 0, unit: '%' },
  };
  var ranges = {}, rangeValues = {};
  Object.keys(SLIDERS).forEach(function (k) {
    ranges[k] = document.getElementById('range' + k);
    rangeValues[k] = document.getElementById('value' + k);
  });

  // Filter presets, expressed as ordered CSS filter primitives so the same
  // list drives both the live preview (CSS filter on the canvas) and the
  // captured file (ctx.filter, or the per-pixel fallback below).
  var PRESETS = {
    none: [],
    vivid: [['saturate', 1.45], ['contrast', 1.1]],
    vividWarm: [['saturate', 1.4], ['contrast', 1.1], ['sepia', 0.2], ['hue-rotate', -8]],
    vividCool: [['saturate', 1.4], ['contrast', 1.1], ['hue-rotate', 12]],
    dramatic: [['contrast', 1.45], ['saturate', 0.85], ['brightness', 0.92]],
    dramaticWarm: [['contrast', 1.4], ['saturate', 0.9], ['sepia', 0.25], ['brightness', 0.92]],
    dramaticCool: [['contrast', 1.4], ['saturate', 0.85], ['hue-rotate', 15], ['brightness', 0.92]],
    mono: [['grayscale', 1]],
    silvertone: [['grayscale', 1], ['brightness', 1.12], ['contrast', 0.9]],
    noir: [['grayscale', 1], ['contrast', 1.6], ['brightness', 0.9]],
    sepia: [['sepia', 1]],
    vintage: [['sepia', 0.45], ['contrast', 0.9], ['saturate', 0.8], ['brightness', 1.05]],
    fade: [['contrast', 0.75], ['saturate', 0.7], ['brightness', 1.1]],
    warm: [['sepia', 0.3], ['saturate', 1.2], ['hue-rotate', -10]],
    cool: [['hue-rotate', 18], ['saturate', 1.1]],
    ice: [['hue-rotate', 25], ['saturate', 0.6], ['brightness', 1.15]],
  };
  var BALANCE = {
    neutral: [],
    warm: [['sepia', 0.18], ['saturate', 1.1], ['hue-rotate', -6]],
    cool: [['hue-rotate', 12], ['saturate', 1.05]],
  };
  var ASPECTS = { free: 0, '1:1': 1, '4:3': 4 / 3, '3:4': 3 / 4, '16:9': 16 / 9, '9:16': 9 / 16 };
  var RESOLUTIONS = { '2160': [3840, 2160], '1440': [2560, 1440], '1080': [1920, 1080], '720': [1280, 720], '480': [640, 480] };

  var currentStream = null;
  var currentDeviceId = '';
  var starting = false;
  var capturing = false;
  var shotCount = 0;
  var captures = []; // {id, n, pngUrl, jpegUrl}
  var MAX_CAPTURES = 6;
  var canvas = document.createElement('canvas');
  var ctx = canvas.getContext('2d');
  var previewCtx = previewCanvas.getContext('2d');
  var gridCtx = gridCanvas.getContext('2d');
  var rafId = 0;
  var gridKey = '';
  var hwExposure = null; // {min, max, step} when the camera exposes exposureCompensation
  var hasTorch = false;
  var pseudoFullscreen = false;
  var ctxFilterSupported = (function () {
    try {
      var c = document.createElement('canvas').getContext('2d');
      if (!('filter' in c)) return false;
      c.filter = 'blur(1px)';
      return c.filter === 'blur(1px)';
    } catch (e) { return false; }
  })();

  function escapeHtml(s) {
    var d = document.createElement('div');
    d.textContent = String(s);
    return d.innerHTML;
  }

  function setDiagnostic(items) {
    diagnosticPanel.innerHTML = items.map(function (it) {
      var sevClass = it.sev ? ' sev-' + it.sev : '';
      return '<div class="diagnostic-item' + sevClass + '"><span class="diag-icon" aria-hidden="true">' +
        '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
        '</span><span>' + it.html + '</span></div>';
    }).join('');
  }

  function formatBytes(n) {
    if (n < 1024) return n + ' B';
    if (n < 1024 * 1024) return (n / 1024).toFixed(1) + ' KB';
    return (n / (1024 * 1024)).toFixed(2) + ' MB';
  }

  function round2(n) { return Math.round(n * 100) / 100; }

  function fileBase() {
    var v = (inputFileName.value || '').trim().replace(/[^A-Za-z0-9 _.-]+/g, '').replace(/\s+/g, '-').replace(/^[.-]+/, '');
    return v || 'webcam-photo';
  }

  function capFileName(cap, ext) {
    return fileBase() + '-' + cap.n + '.' + ext;
  }

  function revokeCapture(cap) {
    URL.revokeObjectURL(cap.pngUrl);
    URL.revokeObjectURL(cap.jpegUrl);
  }

  function renderCaptureList() {
    if (!captures.length) {
      captureList.innerHTML = '';
      captureList.appendChild(captureEmpty);
      return;
    }
    captureList.innerHTML = captures.map(function (cap) {
      return '<div class="capture-row"><span class="capture-row-meta">' + cap.width + '×' + cap.height + ' — ' + cap.time + '</span>' +
        '<span class="capture-row-actions"><a href="' + cap.pngUrl + '" download="' + escapeHtml(capFileName(cap, 'png')) + '">Download PNG</a>' +
        '<a href="' + cap.jpegUrl + '" download="' + escapeHtml(capFileName(cap, 'jpg')) + '">Download JPEG</a></span></div>';
    }).join('');
  }

  // ---------- Settings -> geometry + filter ----------

  function sliderVal(k) { return parseFloat(ranges[k].value) || 0; }

  function filterOps(forCapture) {
    var ops = [];
    (PRESETS[selectFilter.value] || []).forEach(function (o) { ops.push(o); });
    (BALANCE[selectBalance.value] || []).forEach(function (o) { ops.push(o); });
    if (checkNight.checked) { ops.push(['brightness', 1.6]); ops.push(['contrast', 1.15]); ops.push(['saturate', 0.9]); }
    var ev = sliderVal('Exposure');
    if (ev && !hwExposure) ops.push(['brightness', Math.max(0, Math.pow(2, ev / 2))]);
    var b = sliderVal('Brightness'), c = sliderVal('Contrast'), s = sliderVal('Saturation'), h = sliderVal('Hue');
    var g = sliderVal('Grayscale'), sp = sliderVal('Sepia'), inv = sliderVal('Invert'), bl = sliderVal('Blur');
    if (b !== 100) ops.push(['brightness', b / 100]);
    if (c !== 100) ops.push(['contrast', c / 100]);
    if (s !== 100) ops.push(['saturate', s / 100]);
    if (h) ops.push(['hue-rotate', h]);
    if (g) ops.push(['grayscale', g / 100]);
    if (sp) ops.push(['sepia', sp / 100]);
    if (inv) ops.push(['invert', inv / 100]);
    if (bl) ops.push(['blur', bl * (forCapture || 1)]);
    return ops;
  }

  function opsToCss(ops) {
    if (!ops.length) return 'none';
    return ops.map(function (o) {
      var unit = o[0] === 'hue-rotate' ? 'deg' : (o[0] === 'blur' ? 'px' : '');
      return o[0] + '(' + round2(o[1]) + unit + ')';
    }).join(' ');
  }

  function isMirrored() { return previewWrap.classList.contains('is-mirrored'); }

  // Source crop + output size for a vw x vh frame: digital zoom crops the
  // centre, rotation swaps axes, then the aspect ratio trims the long side.
  function computeGeometry(vw, vh) {
    var z = parseFloat(selectZoom.value) || 1;
    var rot = parseInt(selectRotate.value, 10) || 0;
    var rot90 = rot % 180 !== 0;
    var zw = vw / z, zh = vh / z;
    var rw = rot90 ? zh : zw, rh = rot90 ? zw : zh;
    var a = ASPECTS[selectAspect.value] || 0;
    var ow = rw, oh = rh;
    if (a) {
      if (rw / rh > a) { ow = rh * a; oh = rh; } else { ow = rw; oh = rw / a; }
    }
    var cw = rot90 ? oh : ow, ch = rot90 ? ow : oh;
    return {
      sx: (vw - cw) / 2, sy: (vh - ch) / 2, cw: cw, ch: ch,
      outW: Math.max(1, Math.round(ow)), outH: Math.max(1, Math.round(oh)), rot: rot,
    };
  }

  function shapePath(c, w, h, shape) {
    var cx = w / 2, cy = h / 2, r = Math.min(w, h) / 2, i, ang;
    c.beginPath();
    if (shape === 'circle') {
      c.arc(cx, cy, r, 0, Math.PI * 2);
    } else if (shape === 'hexagon') {
      for (i = 0; i < 6; i++) {
        ang = Math.PI / 3 * i - Math.PI / 2;
        c[i ? 'lineTo' : 'moveTo'](cx + r * Math.cos(ang), cy + r * Math.sin(ang));
      }
      c.closePath();
    } else if (shape === 'star') {
      for (i = 0; i < 10; i++) {
        var rr = i % 2 ? r * 0.45 : r;
        ang = Math.PI / 5 * i - Math.PI / 2;
        c[i ? 'lineTo' : 'moveTo'](cx + rr * Math.cos(ang), cy + rr * Math.sin(ang));
      }
      c.closePath();
    } else if (shape === 'heart') {
      var s = r * 2, x0 = cx - r, y0 = cy - r;
      c.moveTo(x0 + s * 0.5, y0 + s * 0.95);
      c.bezierCurveTo(x0 + s * 0.1, y0 + s * 0.65, x0 - s * 0.02, y0 + s * 0.3, x0 + s * 0.22, y0 + s * 0.12);
      c.bezierCurveTo(x0 + s * 0.38, y0 + s * 0.0, x0 + s * 0.5, y0 + s * 0.12, x0 + s * 0.5, y0 + s * 0.25);
      c.bezierCurveTo(x0 + s * 0.5, y0 + s * 0.12, x0 + s * 0.62, y0 + s * 0.0, x0 + s * 0.78, y0 + s * 0.12);
      c.bezierCurveTo(x0 + s * 1.02, y0 + s * 0.3, x0 + s * 0.9, y0 + s * 0.65, x0 + s * 0.5, y0 + s * 0.95);
      c.closePath();
    }
  }

  // Draws the current frame into c (w x h) with crop/rotation/mirror/flip
  // and the optional shape mask. The colour filter is applied separately.
  function drawFrame(c, w, h, g, cssFilter) {
    var mx = isMirrored() ? -1 : 1, my = checkFlipV.checked ? -1 : 1;
    var k = w / g.outW;
    c.save();
    c.clearRect(0, 0, w, h);
    if (cssFilter && cssFilter !== 'none') c.filter = cssFilter;
    c.translate(w / 2, h / 2);
    c.scale(mx, my);
    c.rotate(g.rot * Math.PI / 180);
    c.drawImage(video, g.sx, g.sy, g.cw, g.ch, -g.cw * k / 2, -g.ch * k / 2, g.cw * k, g.ch * k);
    c.restore();
    var shape = selectShape.value;
    if (shape !== 'none') {
      c.save();
      c.globalCompositeOperation = 'destination-in';
      shapePath(c, w, h, shape);
      c.fill();
      c.restore();
    }
  }

  // ---------- Per-pixel filter fallback (browsers without ctx.filter) ----------

  function clamp255(v) { return v < 0 ? 0 : (v > 255 ? 255 : v); }

  function opMatrix(name, v) {
    var c, s, a;
    switch (name) {
      case 'brightness': return [v, 0, 0, 0, v, 0, 0, 0, v, 0];
      case 'contrast': return [v, 0, 0, 0, v, 0, 0, 0, v, 127.5 * (1 - v)];
      case 'saturate': return [
        0.213 + 0.787 * v, 0.715 - 0.715 * v, 0.072 - 0.072 * v,
        0.213 - 0.213 * v, 0.715 + 0.285 * v, 0.072 - 0.072 * v,
        0.213 - 0.213 * v, 0.715 - 0.715 * v, 0.072 + 0.928 * v, 0];
      case 'hue-rotate':
        a = v * Math.PI / 180; c = Math.cos(a); s = Math.sin(a);
        return [
          0.213 + c * 0.787 - s * 0.213, 0.715 - c * 0.715 - s * 0.715, 0.072 - c * 0.072 + s * 0.928,
          0.213 - c * 0.213 + s * 0.143, 0.715 + c * 0.285 + s * 0.140, 0.072 - c * 0.072 - s * 0.283,
          0.213 - c * 0.213 - s * 0.787, 0.715 - c * 0.715 + s * 0.715, 0.072 + c * 0.928 + s * 0.072, 0];
      case 'grayscale': a = 1 - Math.min(1, v); return [
        0.2126 + 0.7874 * a, 0.7152 - 0.7152 * a, 0.0722 - 0.0722 * a,
        0.2126 - 0.2126 * a, 0.7152 + 0.2848 * a, 0.0722 - 0.0722 * a,
        0.2126 - 0.2126 * a, 0.7152 - 0.7152 * a, 0.0722 + 0.9278 * a, 0];
      case 'sepia': a = 1 - Math.min(1, v); return [
        0.393 + 0.607 * a, 0.769 - 0.769 * a, 0.189 - 0.189 * a,
        0.349 - 0.349 * a, 0.686 + 0.314 * a, 0.168 - 0.168 * a,
        0.272 - 0.272 * a, 0.534 - 0.534 * a, 0.131 + 0.869 * a, 0];
      case 'invert': a = Math.min(1, v); return [1 - 2 * a, 0, 0, 0, 1 - 2 * a, 0, 0, 0, 1 - 2 * a, 255 * a];
      default: return null; // blur: not reproduced in the fallback
    }
  }

  function applyOpsToPixels(c, w, h, ops) {
    var mats = ops.map(function (o) { return opMatrix(o[0], o[1]); }).filter(Boolean);
    if (!mats.length) return;
    var img = c.getImageData(0, 0, w, h), d = img.data, i, j, m, r, g, b;
    for (i = 0; i < d.length; i += 4) {
      r = d[i]; g = d[i + 1]; b = d[i + 2];
      for (j = 0; j < mats.length; j++) {
        m = mats[j];
        var nr = clamp255(m[0] * r + m[1] * g + m[2] * b + m[9]);
        var ng = clamp255(m[3] * r + m[4] * g + m[5] * b + m[9]);
        var nb = clamp255(m[6] * r + m[7] * g + m[8] * b + m[9]);
        r = nr; g = ng; b = nb;
      }
      d[i] = r; d[i + 1] = g; d[i + 2] = b;
    }
    c.putImageData(img, 0, 0);
  }

  // ---------- Live preview ----------

  function displayedWidth(w, h) {
    var bw = previewWrap.clientWidth || w, bh = previewWrap.clientHeight || h;
    return Math.min(bw, bh * w / h);
  }

  function renderPreview() {
    rafId = 0;
    if (!currentStream) return;
    var vw = video.videoWidth, vh = video.videoHeight;
    if (vw && vh) {
      var g = computeGeometry(vw, vh);
      var scale = Math.min(1, 1280 / Math.max(g.outW, g.outH));
      var w = Math.max(1, Math.round(g.outW * scale)), h = Math.max(1, Math.round(g.outH * scale));
      if (previewCanvas.width !== w || previewCanvas.height !== h) {
        previewCanvas.width = w; previewCanvas.height = h;
      }
      drawFrame(previewCtx, w, h, g, null);
      drawGrid(w, h);
    }
    rafId = requestAnimationFrame(renderPreview);
  }

  function drawGrid(w, h) {
    var key = w + 'x' + h + ':' + checkGrid.checked;
    if (key === gridKey) return;
    gridKey = key;
    gridCanvas.width = w; gridCanvas.height = h;
    gridCtx.clearRect(0, 0, w, h);
    if (!checkGrid.checked) return;
    gridCtx.strokeStyle = 'rgba(255,255,255,0.75)';
    gridCtx.lineWidth = Math.max(1, Math.round(w / 640));
    gridCtx.shadowColor = 'rgba(0,0,0,0.6)';
    gridCtx.shadowBlur = 2;
    gridCtx.beginPath();
    [1, 2].forEach(function (i) {
      gridCtx.moveTo(w * i / 3, 0); gridCtx.lineTo(w * i / 3, h);
      gridCtx.moveTo(0, h * i / 3); gridCtx.lineTo(w, h * i / 3);
    });
    gridCtx.stroke();
  }

  function updatePreviewFilter() {
    previewCanvas.style.filter = opsToCss(filterOps(1));
  }

  function updateSliderReadouts() {
    Object.keys(SLIDERS).forEach(function (k) {
      var v = sliderVal(k);
      if (k === 'Exposure') rangeValues[k].textContent = (v > 0 ? '+' : '') + v + ' EV';
      else rangeValues[k].textContent = v + SLIDERS[k].unit;
    });
  }

  function onAdjustmentChange() {
    updateSliderReadouts();
    updatePreviewFilter();
  }

  function applyHardwareExposure() {
    if (!hwExposure || !currentStream) return;
    var track = currentStream.getVideoTracks()[0];
    var v = Math.max(hwExposure.min, Math.min(hwExposure.max, sliderVal('Exposure')));
    track.applyConstraints({ advanced: [{ exposureMode: 'continuous', exposureCompensation: v }] }).catch(function () {});
  }

  function readCapabilities(track) {
    hwExposure = null;
    hasTorch = false;
    torchOn = false;
    var caps = track.getCapabilities ? track.getCapabilities() : {};
    if (caps.exposureCompensation && typeof caps.exposureCompensation.max === 'number' && caps.exposureCompensation.max > caps.exposureCompensation.min) {
      hwExposure = { min: caps.exposureCompensation.min, max: caps.exposureCompensation.max };
    }
    hasTorch = !!caps.torch;
    adjustmentsNote.textContent = hwExposure
      ? 'Exposure is applied by your camera itself (hardware exposure compensation), so it changes what the sensor captures.'
      : 'Your camera doesn’t expose hardware exposure control to the browser, so Exposure is applied as a brightness boost instead.';
    applyHardwareExposure();
    updatePreviewFilter();
  }

  // ---------- Camera acquisition / teardown ----------

  // Every camera page on this site copies this stopStream()/enumerate/error
  // pattern from webcam-test-online.json (see this project's own CLAUDE.md).
  // This tool additionally revokes every outstanding capture object URL on
  // teardown (pagehide), so leaving the page never leaks blob memory.
  function stopStream() {
    if (rafId) { cancelAnimationFrame(rafId); rafId = 0; }
    if (currentStream) {
      currentStream.getTracks().forEach(function (t) { t.stop(); });
      currentStream = null;
    }
    exitFullscreenView();
    video.srcObject = null;
    video.style.visibility = '';
    previewCanvas.width = 0; previewCanvas.height = 0;
    gridCanvas.width = 0; gridCanvas.height = 0;
    gridKey = '';
    previewWrap.classList.remove('is-active');
    placeholder.style.display = 'flex';
    btnStop.disabled = true;
    btnMirror.disabled = true;
    btnFullscreen.disabled = true;
    btnCapture.disabled = true;
    selectCountdown.disabled = true;
    checkBurst.disabled = true;
  }

  function describeError(err) {
    switch (err && err.name) {
      case 'NotAllowedError':
      case 'PermissionDeniedError':
        return { sev: 'error', html: '<strong>Camera access was blocked.</strong> Click the camera icon in your address bar (or your browser’s site settings) and allow access, then try again.' };
      case 'NotFoundError':
      case 'DevicesNotFoundError':
        return { sev: 'error', html: '<strong>No camera was detected.</strong> Make sure a webcam is connected, then reload this page.' };
      case 'NotReadableError':
      case 'TrackStartError':
        return { sev: 'error', html: '<strong>Your camera is already in use.</strong> Another app or browser tab is probably holding it — close video-calling apps or other camera tabs and try again.' };
      case 'OverconstrainedError':
      case 'ConstraintNotSatisfiedError':
        return { sev: 'error', html: '<strong>This camera doesn’t support the requested settings.</strong> Try a different camera or a lower resolution from the lists above.' };
      case 'SecurityError':
        return { sev: 'error', html: '<strong>Camera access requires a secure connection.</strong> Make sure this page is loaded over HTTPS.' };
      case 'AbortError':
        return { sev: 'warn', html: 'The camera request was interrupted. Click <strong>Start Camera</strong> to try again.' };
      default:
        return { sev: 'error', html: '<strong>Something went wrong starting the camera.</strong> ' + escapeHtml((err && err.message) || 'Unknown error') + '.' };
    }
  }

  function populateDeviceSelect(devices) {
    var cams = devices.filter(function (d) { return d.kind === 'videoinput'; });
    deviceSelect.innerHTML = '';
    if (!cams.length) {
      var opt = document.createElement('option');
      opt.value = '';
      opt.textContent = 'No cameras found';
      deviceSelect.appendChild(opt);
      deviceSelect.disabled = true;
      return;
    }
    cams.forEach(function (d, i) {
      var opt = document.createElement('option');
      opt.value = d.deviceId;
      opt.textContent = d.label || ('Camera ' + (i + 1));
      if (d.deviceId === currentDeviceId) opt.selected = true;
      deviceSelect.appendChild(opt);
    });
    deviceSelect.disabled = false;
  }

  function refreshDeviceList() {
    if (!navigator.mediaDevices || !navigator.mediaDevices.enumerateDevices) return Promise.resolve();
    return navigator.mediaDevices.enumerateDevices().then(populateDeviceSelect).catch(function () {});
  }

  function buildVideoConstraint(deviceId) {
    var res = selectResolution.value;
    var c = {};
    if (res === 'max') { c.width = { ideal: 4096 }; c.height = { ideal: 2160 }; }
    else if (RESOLUTIONS[res]) { c.width = { ideal: RESOLUTIONS[res][0] }; c.height = { ideal: RESOLUTIONS[res][1] }; }
    if (deviceId) c.deviceId = { exact: deviceId };
    return Object.keys(c).length ? c : true;
  }

  function startStream(deviceId) {
    if (starting) return;
    starting = true;
    stopStream();
    setDiagnostic([{ sev: '', html: 'Requesting camera access…' }]);
    btnStart.disabled = true;

    navigator.mediaDevices.getUserMedia({ video: buildVideoConstraint(deviceId), audio: false })
      .then(function (stream) {
        currentStream = stream;
        video.srcObject = stream;
        placeholder.style.display = 'none';
        previewWrap.classList.add('is-active');
        return video.play().catch(function () {}).then(function () { return stream; });
      })
      .then(function (stream) {
        var track = stream.getVideoTracks()[0];
        var settings = track.getSettings ? track.getSettings() : {};
        currentDeviceId = settings.deviceId || deviceId || '';
        // The canvas preview replaces the raw <video> on screen so the
        // visitor sees crop, rotation, shape and filters before shooting.
        video.style.visibility = 'hidden';
        readCapabilities(track);
        if (!rafId) rafId = requestAnimationFrame(renderPreview);
        btnStop.disabled = false;
        btnMirror.disabled = false;
        btnFullscreen.disabled = false;
        btnCapture.disabled = false;
        selectCountdown.disabled = false;
        checkBurst.disabled = false;
        var w = video.videoWidth || settings.width, h = video.videoHeight || settings.height;
        setDiagnostic([{ sev: 'ok', html: '<strong>Camera is live' + (w && h ? ' at ' + w + '×' + h : '') + '.</strong> Click <strong>Capture Photo</strong> to take a still.' }]);
        return refreshDeviceList();
      })
      .catch(function (err) {
        setDiagnostic([describeError(err)]);
      })
      .finally(function () {
        starting = false;
        btnStart.disabled = false;
      });
  }

  // ---------- Capture ----------

  function toBlobP(c, type, quality) {
    return new Promise(function (resolve) {
      c.toBlob(function (blob) { resolve(blob); }, type, quality);
    });
  }

  // Draws at the stream's real dimensions (video.videoWidth/videoHeight),
  // never the displayed element size, so the camera's native resolution is
  // captured (minus whatever zoom/aspect crop the visitor chose).
  function grabFrame() {
    var vw = video.videoWidth, vh = video.videoHeight;
    if (!vw || !vh) return Promise.reject(new Error('Video has no dimensions yet'));
    var g = computeGeometry(vw, vh);
    canvas.width = g.outW;
    canvas.height = g.outH;
    var blurScale = g.outW / Math.max(1, displayedWidth(g.outW, g.outH));
    var ops = filterOps(blurScale);
    drawFrame(ctx, g.outW, g.outH, g, ctxFilterSupported ? opsToCss(ops) : null);
    if (!ctxFilterSupported) applyOpsToPixels(ctx, g.outW, g.outH, ops);
    // JPEG has no alpha channel: give shaped photos a white background.
    var flat = canvas;
    if (selectShape.value !== 'none') {
      flat = document.createElement('canvas');
      flat.width = g.outW; flat.height = g.outH;
      var fctx = flat.getContext('2d');
      fctx.fillStyle = '#fff';
      fctx.fillRect(0, 0, g.outW, g.outH);
      fctx.drawImage(canvas, 0, 0);
    }
    return Promise.all([
      toBlobP(canvas, 'image/png'),
      toBlobP(flat, 'image/jpeg', 0.92),
    ]).then(function (blobs) {
      return { width: g.outW, height: g.outH, srcW: vw, srcH: vh, png: blobs[0], jpeg: blobs[1] };
    });
  }

  function flash() {
    if (!checkFlash.checked) return;
    flashEl.classList.add('flash');
    requestAnimationFrame(function () {
      flashEl.classList.remove('flash');
    });
  }

  var torchOn = false;
  function setTorch(on) {
    if (!hasTorch || !currentStream) return Promise.resolve();
    if (on && !checkFlash.checked) return Promise.resolve();
    if (!on && !torchOn) return Promise.resolve();
    torchOn = on;
    var track = currentStream.getVideoTracks()[0];
    return track.applyConstraints({ advanced: [{ torch: on }] }).catch(function () {}).then(function () {
      return on ? delay(350) : null;
    });
  }

  function describeEffects() {
    var parts = [];
    if (selectFilter.value !== 'none') parts.push(selectFilter.options[selectFilter.selectedIndex].text);
    if (selectBalance.value !== 'neutral') parts.push(selectBalance.value + ' balance');
    if (checkNight.checked) parts.push('night');
    if (isMirrored()) parts.push('mirrored');
    if (checkFlipV.checked) parts.push('flipped');
    if (selectRotate.value !== '0') parts.push(selectRotate.value + '°');
    if (selectZoom.value !== '1') parts.push(selectZoom.value + '× zoom');
    if (selectShape.value !== 'none') parts.push(selectShape.value);
    var adjusted = Object.keys(SLIDERS).some(function (k) { return sliderVal(k) !== SLIDERS[k].def; });
    if (adjusted) parts.push('adjusted');
    return parts.join(', ') || 'None';
  }

  function addCapture(result) {
    shotCount++;
    var now = new Date();
    var cap = {
      id: now.getTime() + '-' + shotCount,
      n: shotCount,
      time: now.toLocaleTimeString(),
      width: result.width,
      height: result.height,
      pngUrl: URL.createObjectURL(result.png),
      jpegUrl: URL.createObjectURL(result.jpeg),
    };
    captures.unshift(cap);
    while (captures.length > MAX_CAPTURES) {
      revokeCapture(captures.pop());
    }
    var w = result.width, h = result.height;
    statResolution.textContent = w + '×' + h;
    statMegapixels.textContent = (w * h / 1e6).toFixed(2) + ' MP';
    statFrameKept.textContent = Math.round(w * h / (result.srcW * result.srcH) * 1000) / 10 + '%';
    statPrintSize.textContent = round2(w / 300) + ' × ' + round2(h / 300) + ' in';
    statOrientation.textContent = w === h ? 'Square' : (w > h ? 'Landscape' : 'Portrait');
    statPngSize.textContent = formatBytes(result.png.size);
    statJpegSize.textContent = formatBytes(result.jpeg.size);
    var cd = parseInt(selectCountdown.value, 10) || 0;
    statDelay.textContent = cd ? cd + ' s self-timer' : 'Instant';
    statEffects.textContent = describeEffects();
    statSavedFile.textContent = capFileName(cap, 'png') + ' / .jpg';
    statShotCount.textContent = String(shotCount);
    renderCaptureList();
    flash();
  }

  function doCapture() {
    return grabFrame().then(addCapture).catch(function () {
      setDiagnostic([{ sev: 'error', html: '<strong>Could not capture a frame.</strong> Make sure the camera is live and try again.' }]);
    });
  }

  function runCountdown(seconds) {
    return new Promise(function (resolve) {
      if (!seconds) { resolve(); return; }
      var remaining = seconds;
      countdownEl.textContent = String(remaining);
      countdownEl.classList.add('show');
      var tick = setInterval(function () {
        remaining--;
        if (remaining <= 0 || !currentStream) {
          clearInterval(tick);
          countdownEl.classList.remove('show');
          resolve();
          return;
        }
        countdownEl.textContent = String(remaining);
      }, 1000);
    });
  }

  function delay(ms) {
    return new Promise(function (resolve) { setTimeout(resolve, ms); });
  }

  function capturePhoto() {
    if (capturing || !currentStream) return;
    capturing = true;
    btnCapture.disabled = true;
    var seconds = parseInt(selectCountdown.value, 10) || 0;
    var burst = checkBurst.checked;

    runCountdown(seconds)
      .then(function () { return currentStream ? setTorch(true) : null; })
      .then(function () { return currentStream ? doCapture() : null; })
      .then(function () {
        if (!burst || !currentStream) return;
        return delay(700).then(doCapture).then(function () {
          return delay(700).then(doCapture);
        });
      })
      .finally(function () {
        setTorch(false);
        capturing = false;
        btnCapture.disabled = !currentStream;
      });
  }

  // ---------- Fullscreen (pattern from webcam-fullscreen-viewer.json) ----------

  function isFullscreenActive() {
    return document.fullscreenElement === previewWrap || pseudoFullscreen;
  }

  function enterFullscreenView() {
    if (!currentStream || isFullscreenActive()) return;
    var request = previewWrap.requestFullscreen ? previewWrap.requestFullscreen() : null;
    if (request && request.then) {
      request.catch(function () { enterPseudoFullscreen(); });
    } else if (!document.fullscreenEnabled) {
      enterPseudoFullscreen();
    }
  }

  function enterPseudoFullscreen() {
    pseudoFullscreen = true;
    previewWrap.classList.add('is-pseudo-fullscreen');
    afterEnterFullscreen();
  }

  function afterEnterFullscreen() {
    btnFullscreen.textContent = 'Exit Fullscreen';
    btnExitFullscreen.classList.remove('u-hidden');
    fullscreenHint.classList.add('show');
    setTimeout(function () { fullscreenHint.classList.remove('show'); }, 2500);
  }

  function exitFullscreenView() {
    if (document.fullscreenElement === previewWrap) {
      var p = document.exitFullscreen();
      if (p && p.catch) p.catch(function () {});
      return;
    }
    if (pseudoFullscreen) {
      pseudoFullscreen = false;
      previewWrap.classList.remove('is-pseudo-fullscreen');
      afterExitFullscreen();
    }
  }

  function afterExitFullscreen() {
    btnFullscreen.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M8 3H5a2 2 0 0 0-2 2v3M16 3h3a2 2 0 0 1 2 2v3M21 16v3a2 2 0 0 1-2 2h-3M3 16v3a2 2 0 0 0 2 2h3" stroke-linecap="round" stroke-linejoin="round"/></svg>Fullscreen';
    btnExitFullscreen.classList.add('u-hidden');
    fullscreenHint.classList.remove('show');
  }

  document.addEventListener('fullscreenchange', function () {
    if (document.fullscreenElement === previewWrap) afterEnterFullscreen();
    else if (!pseudoFullscreen) afterExitFullscreen();
  });

  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && isFullscreenActive()) exitFullscreenView();
  });

  // ---------- Wiring ----------

  btnStart.addEventListener('click', function () { startStream(deviceSelect.value); });
  btnStop.addEventListener('click', function () {
    stopStream();
    setDiagnostic([{ sev: '', html: 'Camera stopped. Click <strong>Start Camera</strong> to test again.' }]);
  });
  btnMirror.addEventListener('click', function () {
    var mirrored = previewWrap.classList.toggle('is-mirrored');
    btnMirror.setAttribute('aria-pressed', mirrored ? 'true' : 'false');
    btnMirror.classList.toggle('active', mirrored);
  });
  btnFullscreen.addEventListener('click', function () {
    if (isFullscreenActive()) exitFullscreenView(); else enterFullscreenView();
  });
  btnExitFullscreen.addEventListener('click', exitFullscreenView);
  btnCapture.addEventListener('click', capturePhoto);
  deviceSelect.addEventListener('change', function () {
    if (currentStream) startStream(deviceSelect.value);
  });
  selectResolution.addEventListener('change', function () {
    if (currentStream && !capturing) startStream(deviceSelect.value);
  });
  checkGrid.addEventListener('change', function () { gridKey = ''; });
  [selectFilter, selectBalance, checkNight].forEach(function (el) {
    el.addEventListener('change', onAdjustmentChange);
  });
  Object.keys(ranges).forEach(function (k) {
    ranges[k].addEventListener('input', function () {
      onAdjustmentChange();
      if (k === 'Exposure') applyHardwareExposure();
    });
  });
  btnResetAdjustments.addEventListener('click', function () {
    Object.keys(SLIDERS).forEach(function (k) { ranges[k].value = SLIDERS[k].def; });
    selectFilter.value = 'none';
    selectBalance.value = 'neutral';
    checkNight.checked = false;
    onAdjustmentChange();
    applyHardwareExposure();
  });
  inputFileName.addEventListener('input', function () {
    renderCaptureList();
    if (captures.length) statSavedFile.textContent = capFileName(captures[0], 'png') + ' / .jpg';
  });

  // Guaranteed teardown: release the camera and every outstanding capture
  // URL the moment the visitor leaves this page, even if they never
  // clicked Stop.
  window.addEventListener('pagehide', function () {
    stopStream();
    captures.forEach(revokeCapture);
    captures = [];
  });
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') stopStream();
  });

  // Both canvases keep their intrinsic aspect ratio inside the 16:9 box
  // (the shared .media-preview canvas rule stretches them to 100% x 100%).
  previewCanvas.style.objectFit = 'contain';
  gridCanvas.style.objectFit = 'contain';
  updateSliderReadouts();
  updatePreviewFilter();

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    setDiagnostic([{ sev: 'error', html: '<strong>Your browser doesn’t support camera access.</strong> Try the latest version of Chrome, Firefox, Edge, or Safari.' }]);
    btnStart.disabled = true;
  } else {
    setDiagnostic([{ sev: '', html: 'Click <strong>Start Camera</strong> and allow access when your browser asks.' }]);
  }
})();
